using System;
using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Input;

namespace WPFDemo
{
    // Model
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
    }

    // ObservableObject 基类
    public class ObservableObject : INotifyPropertyChanged
    {
        public event PropertyChangedEventHandler PropertyChanged;

        protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }

        protected bool SetProperty<T>(ref T field, T value, [CallerMemberName] string propertyName = null)
        {
            if (EqualityComparer<T>.Default.Equals(field, value))
                return false;

            field = value;
            OnPropertyChanged(propertyName);
            return true;
        }
    }

    // RelayCommand
    public class RelayCommand : ICommand
    {
        private readonly Action<object> _execute;
        private readonly Predicate<object> _canExecute;

        public RelayCommand(Action<object> execute, Predicate<object> canExecute = null)
        {
            _execute = execute ?? throw new ArgumentNullException(nameof(execute));
            _canExecute = canExecute;
        }

        public event EventHandler CanExecuteChanged
        {
            add => CommandManager.RequerySuggested += value;
            remove => CommandManager.RequerySuggested -= value;
        }

        public bool CanExecute(object parameter) => _canExecute?.Invoke(parameter) ?? true;
        public void Execute(object parameter) => _execute(parameter);
    }

    // ViewModel
    public class MainViewModel : ObservableObject
    {
        private readonly IUserRepository _repository;

        private string _userName;
        private string _email;
        private User _selectedUser;
        private string _statusMessage;

        public MainViewModel(IUserRepository repository)
        {
            _repository = repository;
            Users = new ObservableCollection<User>();

            LoadCommand = new RelayCommand(_ => LoadUsers());
            SaveCommand = new RelayCommand(_ => SaveUser(), _ => CanSaveUser());
            DeleteCommand = new RelayCommand(_ => DeleteUser(), _ => SelectedUser != null);

            LoadUsers();
        }

        public ObservableCollection<User> Users { get; }

        public string UserName
        {
            get => _userName;
            set => SetProperty(ref _userName, value);
        }

        public string Email
        {
            get => _email;
            set => SetProperty(ref _email, value);
        }

        public User SelectedUser
        {
            get => _selectedUser;
            set
            {
                if (SetProperty(ref _selectedUser, value) && value != null)
                {
                    UserName = value.Name;
                    Email = value.Email;
                }
            }
        }

        public string StatusMessage
        {
            get => _statusMessage;
            set => SetProperty(ref _statusMessage, value);
        }

        public ICommand LoadCommand { get; }
        public ICommand SaveCommand { get; }
        public ICommand DeleteCommand { get; }

        private async void LoadUsers()
        {
            var users = await _repository.GetAllAsync();
            Users.Clear();
            foreach (var user in users)
            {
                Users.Add(user);
            }
            StatusMessage = $"已加载 {Users.Count} 个用户";
        }

        private async void SaveUser()
        {
            if (SelectedUser == null)
            {
                var newUser = new User { Name = UserName, Email = Email };
                await _repository.AddAsync(newUser);
                Users.Add(newUser);
                StatusMessage = "用户已添加";
            }
            else
            {
                SelectedUser.Name = UserName;
                SelectedUser.Email = Email;
                await _repository.UpdateAsync(SelectedUser);
                StatusMessage = "用户已更新";
            }
        }

        private bool CanSaveUser()
        {
            return !string.IsNullOrWhiteSpace(UserName) &&
                   !string.IsNullOrWhiteSpace(Email);
        }

        private async void DeleteUser()
        {
            if (SelectedUser != null)
            {
                await _repository.DeleteAsync(SelectedUser.Id);
                Users.Remove(SelectedUser);
                SelectedUser = null;
                UserName = string.Empty;
                Email = string.Empty;
                StatusMessage = "用户已删除";
            }
        }
    }

    // 自定义依赖属性控件
    public class ValidationTextBox : System.Windows.Controls.TextBox
    {
        public static readonly DependencyProperty LabelProperty =
            DependencyProperty.Register(
                nameof(Label),
                typeof(string),
