                new PropertyMetadata(string.Empty));

        public string Label
        {
            get => (string)GetValue(LabelProperty);
            set => SetValue(LabelProperty, value);
        }

        public bool IsRequired
        {
            get => (bool)GetValue(IsRequiredProperty);
            set => SetValue(IsRequiredProperty, value);
        }

        public string ErrorMessage
        {
            get => (string)GetValue(ErrorMessageProperty);
            set => SetValue(ErrorMessageProperty, value);
        }
    }

    // 路由事件示例
    public class CustomButton : System.Windows.Controls.Button
    {
        public static readonly RoutedEvent LongPressEvent =
            EventManager.RegisterRoutedEvent(
                "LongPress",
                RoutingStrategy.Bubble,
                typeof(RoutedEventHandler),
                typeof(CustomButton));

        public event RoutedEventHandler LongPress
        {
            add => AddHandler(LongPressEvent, value);
            remove => RemoveHandler(LongPressEvent, value);
        }

        private DateTime _mouseDownTime;

        protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e)
        {
            base.OnMouseLeftButtonDown(e);
            _mouseDownTime = DateTime.Now;
        }

        protected override void OnMouseLeftButtonUp(MouseButtonEventArgs e)
        {
            base.OnMouseLeftButtonUp(e);
            var duration = DateTime.Now - _mouseDownTime;
            if (duration.TotalMilliseconds > 500)
            {
                RaiseEvent(new RoutedEventArgs(LongPressEvent));
            }
        }
    }

    // Repository 接口
    public interface IUserRepository
    {
        Task<IEnumerable<User>> GetAllAsync();
        Task<User> GetByIdAsync(int id);
        Task AddAsync(User user);
        Task UpdateAsync(User user);
        Task DeleteAsync(int id);
    }

    // 应用入口
    public partial class App : Application
    {
        protected override void OnStartup(StartupEventArgs e)
        {
            base.OnStartup(e);

            var mainWindow = new MainWindow
            {
                DataContext = new MainViewModel(new InMemoryUserRepository())
            };
            mainWindow.Show();
        }
    }

    // 内存仓储实现
    public class InMemoryUserRepository : IUserRepository
    {
        private readonly List<User> _users = new();
        private int _nextId = 1;

        public Task<IEnumerable<User>> GetAllAsync()
        {
            return Task.FromResult(_users.AsEnumerable());
        }

        public Task<User> GetByIdAsync(int id)
        {
            return Task.FromResult(_users.FirstOrDefault(u => u.Id == id));
        }

        public Task AddAsync(User user)
        {
            user.Id = _nextId++;
            _users.Add(user);
            return Task.CompletedTask;
        }

        public Task UpdateAsync(User user)
        {
            var existing = _users.FirstOrDefault(u => u.Id == user.Id);
            if (existing != null)
            {
                existing.Name = user.Name;
                existing.Email = user.Email;
            }
            return Task.CompletedTask;
        }

        public Task DeleteAsync(int id)
        {
            var user = _users.FirstOrDefault(u => u.Id == id);
            if (user != null)
            {
                _users.Remove(user);
            }
            return Task.CompletedTask;
        }
    }
}
